mapper.select:
SELECT smac.id, smac.user_id, smac.`state`, smac.app_id, smac.app_key, smac.expire_date, smac.system_name, smac.white_ips, smac.note, ifnull(su.user_real_cn_name,stu.user_real_cn_name) as bind_user, smac.tenant_name, smac.create_time,smac.org_id,smac.bind_type,smac.create_user_cn_name FROM sys_hmac_user smac LEFT JOIN sys_user su ON smac.user_id = su.id and smac.bind_type='user' LEFT JOIN sys_tenant tu on smac.tenant_id = tu.id and smac.bind_type='tenant' LEFT JOIN sys_tenant_user stu ON smac.user_id = stu.id and stu.tenant_id = tu.id
AND smac.system_name LIKE CONCAT('%',#{systemName,jdbcType=CHAR},'%')
AND smac.app_id LIKE CONCAT('%',#{appId,jdbcType=CHAR},'%')
AND smac.user_id = #{userId,jdbcType=CHAR}
AND smac.bind_type = #{bindType,jdbcType=CHAR}
ORDER BY smac.create_time desc LIMIT #{offset,jdbcType=INTEGER}, #{limit,jdbcType=INTEGER}

SELECT count(1)
FROM sys_hmac_user smac


        AND smac.system_name LIKE CONCAT('%',#{systemName,jdbcType=CHAR},'%')


        AND smac.app_id LIKE CONCAT('%',#{appId,jdbcType=CHAR},'%')


        AND smac.user_id = #{userId,jdbcType=CHAR}


        AND smac.bind_type = #{bindType,jdbcType=CHAR}
